<script setup>
/**
 * AppHeader.vue - 顶部导航栏组件
 * 
 * 功能:
 * - 固定定位，滚动时添加阴影/背景效果
 * - Logo: 荆楚遗韵
 * - 导航链接: 首页、非遗概览、传承人、在线学习、视听中心、非遗资讯、非遗地图、文创商城、交流社区
 * - 搜索框: 支持跳转到搜索页面
 * - 用户区域: 登录/注册按钮 或 用户头像 (根据登录状态)
 * - 移动端: 汉堡菜单 + 侧边栏导航
 * 
 * Emits: none
 */

import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useStore } from 'vuex'
import { useRouter, useRoute } from 'vue-router'

const store = useStore()
const router = useRouter()
const route = useRoute()

// ===== 响应式状态 =====
const isScrolled = ref(false)
const mobileMenuOpen = ref(false)
const searchKeyword = ref('')

// ===== 计算属性 =====
const isLoggedIn = computed(() => store.state.isLoggedIn)
const user = computed(() => store.state.user)
const cartCount = computed(() => store.getters.cartCount)

// 当前路由名称 (用于高亮激活的导航项)
const currentRouteName = computed(() => route.name)

// ===== 导航链接配置 =====
const navLinks = [
  { name: 'Home', label: '首页', path: '/' },
  { name: 'Heritage', label: '非遗概览', path: '/heritage' },
  { name: 'Inheritors', label: '传承人', path: '/inheritors' },
  { name: 'Learning', label: '在线学习', path: '/learning' },
  { name: 'Videos', label: '视听中心', path: '/videos' },
  { name: 'News', label: '非遗资讯', path: '/news' },
  { name: 'Map', label: '非遗地图', path: '/map' },
  { name: 'Shop', label: '文创商城', path: '/shop' },
  { name: 'Community', label: '交流社区', path: '/community' }
]

// ===== 滚动监听 =====
const handleScroll = () => {
  isScrolled.value = window.scrollY > 10
}

onMounted(() => {
  window.addEventListener('scroll', handleScroll, { passive: true })
  handleScroll() // 初始化状态
})

onUnmounted(() => {
  window.removeEventListener('scroll', handleScroll)
})

// ===== 方法 =====

// 导航到指定页面
const navigateTo = (path) => {
  mobileMenuOpen.value = false
  router.push(path)
}

// 执行搜索
const handleSearch = () => {
  const keyword = searchKeyword.value.trim()
  if (keyword) {
    router.push({ path: '/search', query: { q: keyword } })
    searchKeyword.value = ''
    mobileMenuOpen.value = false
  }
}

// 处理搜索框回车事件
const handleSearchKeydown = (e) => {
  if (e.key === 'Enter') {
    handleSearch()
  }
}

// 用户登出
const handleLogout = () => {
  store.dispatch('logout')
  mobileMenuOpen.value = false
  router.push('/')
}

// 切换移动端菜单
const toggleMobileMenu = () => {
  mobileMenuOpen.value = !mobileMenuOpen.value
}

// 关闭移动端菜单
const closeMobileMenu = () => {
  mobileMenuOpen.value = false
}
</script>

<template>
  <header
    class="app-header"
    :class="{ 'is-scrolled': isScrolled, 'menu-open': mobileMenuOpen }"
  >
    <div class="header-container">
      <!-- Logo 区域 -->
      <div class="logo" @click="navigateTo('/')">
        <span class="logo-icon">🏛️</span>
        <span class="logo-text">荆楚遗韵</span>
      </div>

      <!-- 桌面端导航链接 -->
      <nav class="desktop-nav">
        <a
          v-for="link in navLinks"
          :key="link.name"
          class="nav-link"
          :class="{ active: currentRouteName === link.name }"
          @click.prevent="navigateTo(link.path)"
        >
          {{ link.label }}
        </a>
      </nav>

      <!-- 右侧操作区 -->
      <div class="header-actions">
        <!-- 搜索框 -->
        <div class="search-box">
          <input
            v-model="searchKeyword"
            type="text"
            placeholder="搜索..."
            class="search-input"
            @keydown="handleSearchKeydown"
          />
          <button class="search-btn" @click="handleSearch" aria-label="搜索">
            🔍
          </button>
        </div>

        <!-- 购物车入口 -->
        <button
          class="action-btn cart-btn"
          @click="navigateTo('/shop')"
          aria-label="购物车"
          title="购物车"
        >
          🛒
          <span v-if="cartCount > 0" class="cart-badge">{{ cartCount }}</span>
        </button>

        <!-- 用户区域 (未登录) -->
        <div v-if="!isLoggedIn" class="auth-buttons">
          <button class="btn-login" @click="navigateTo('/login')">
            登录
          </button>
          <button class="btn-register" @click="navigateTo('/register')">
            注册
          </button>
        </div>

        <!-- 用户区域 (已登录) -->
        <div v-else class="user-info">
          <div class="user-avatar" :title="user?.nickname || user?.username">
            {{ (user?.nickname || user?.username || 'U').charAt(0).toUpperCase() }}
          </div>
          <div class="user-dropdown">
            <div class="dropdown-item" @click="navigateTo('/community')">
              我的社区
            </div>
            <div class="dropdown-item" @click="handleLogout">
              退出登录
            </div>
          </div>
        </div>

        <!-- 移动端汉堡菜单按钮 -->
        <button
          class="hamburger-btn"
          :class="{ open: mobileMenuOpen }"
          @click="toggleMobileMenu"
          aria-label="切换菜单"
        >
          <span></span>
          <span></span>
          <span></span>
        </button>
      </div>
    </div>

    <!-- 移动端侧边栏菜单 -->
    <Transition name="slide">
      <div v-if="mobileMenuOpen" class="mobile-menu-overlay" @click.self="closeMobileMenu">
        <nav class="mobile-nav">
          <div class="mobile-nav-header">
            <span class="mobile-logo">荆楚遗韵</span>
            <button class="close-btn" @click="closeMobileMenu" aria-label="关闭菜单">✕</button>
          </div>

          <!-- 移动端搜索 -->
          <div class="mobile-search">
            <input
              v-model="searchKeyword"
