            />
            <button class="mobile-search-btn" @click="handleSearch">搜索</button>
          </div>

          <!-- 移动端导航链接 -->
          <a
            v-for="link in navLinks"
            :key="link.name"
            class="mobile-nav-link"
            :class="{ active: currentRouteName === link.name }"
            @click.prevent="navigateTo(link.path)"
          >
            {{ link.label }}
          </a>

          <!-- 移动端用户区域 -->
          <div v-if="isLoggedIn" class="mobile-user-section">
            <div class="mobile-user-info">
              <div class="mobile-avatar">
                {{ (user?.nickname || user?.username || 'U').charAt(0).toUpperCase() }}
              </div>
              <span class="mobile-username">{{ user?.nickname || user?.username }}</span>
            </div>
            <button class="mobile-logout-btn" @click="handleLogout">
              退出登录
            </button>
          </div>
          <div v-else class="mobile-auth-buttons">
            <button class="mobile-btn-login" @click="navigateTo('/login')">登录</button>
