<script setup>
/**
 * LoadingSpinner.vue - CSS旋转动画加载指示器
 * 
 * Props:
 * - size: 'small' | 'medium' | 'large' - 尺寸 (默认: medium)
 * - text: string - 可选的加载提示文字
 */

defineProps({
  size: {
    type: String,
    default: 'medium',
    validator(value) {
      return ['small', 'medium', 'large'].includes(value)
    }
  },
  text: {
    type: String,
    default: ''
  }
})
</script>

<template>
  <div class="loading-spinner" :class="`size-${size}`">
    <div class="spinner-container">
      <div class="spinner-ring"></div>
      <div class="spinner-ring spinner-ring-delayed"></div>
    </div>
    <p v-if="text" class="spinner-text">{{ text }}</p>
  </div>
</template>

<style scoped>
/* ===== 加载器容器 ===== */
.loading-spinner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

/* ===== 旋转环容器 ===== */
.spinner-container {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== 旋转环 ===== */
.spinner-ring {
