/**
 * Vuex Store - 全局状态管理
 * 
 * 模块划分:
 * - UI 状态: loading, error
 * - 数据缓存: heritages, inheritors, courses, videos, news, products, posts, mapPoints, searchResults
 * - 分类数据: heritageCategories, courseCategories, videoCategories, newsCategories, productCategories
 * - 用户状态: user, isLoggedIn, token
 * - 购物车: cart
 * 
 * 所有异步 Action 均使用 try/catch 错误处理，并自动 commit SET_ERROR
 */

import { createStore } from 'vuex'

// ===== State =====
const state = {
  // UI 状态
  loading: false,
  error: null,
  sidebarOpen: false,

  // 非遗项目数据
  heritages: [],
  heritageCategories: [],

  // 传承人数据
  inheritors: [],

  // 在线学习数据
  courses: [],
  courseCategories: [],

  // 视听中心数据
  videos: [],
  videoCategories: [],

  // 非遗资讯数据
  news: [],
  newsCategories: [],

  // 文创商城数据
  products: [],
  productCategories: [],

  // 社区数据
  posts: [],

  // 地图数据
  mapPoints: [],

  // 搜索结果
  searchResults: [],

  // 用户状态 (从 localStorage 恢复)
  user: JSON.parse(localStorage.getItem('user') || 'null'),
  isLoggedIn: !!localStorage.getItem('token'),
  token: localStorage.getItem('token') || null,

  // 购物车 (从 localStorage 恢复)
  cart: JSON.parse(localStorage.getItem('cart') || '[]')
}

// ===== Mutations =====
const mutations = {
  // --- UI 状态 ---
  SET_LOADING(state, value) {
    state.loading = value
  },

  SET_ERROR(state, error) {
    state.error = error?.message || error || null
  },

  CLEAR_ERROR(state) {
    state.error = null
  },

  SET_SIDEBAR_OPEN(state, value) {
    state.sidebarOpen = value
  },

  // --- 非遗项目 ---
  SET_HERITAGES(state, data) {
    state.heritages = data
  },

  SET_HERITAGE_CATEGORIES(state, data) {
    state.heritageCategories = data
  },

  // --- 传承人 ---
  SET_INHERITORS(state, data) {
    state.inheritors = data
  },

  // --- 在线学习 ---
  SET_COURSES(state, data) {
    state.courses = data
  },

  SET_COURSE_CATEGORIES(state, data) {
    state.courseCategories = data
  },

  // --- 视听中心 ---
  SET_VIDEOS(state, data) {
    state.videos = data
  },

  SET_VIDEO_CATEGORIES(state, data) {
    state.videoCategories = data
  },

  // --- 非遗资讯 ---
  SET_NEWS(state, data) {
    state.news = data
  },

  SET_NEWS_CATEGORIES(state, data) {
    state.newsCategories = data
  },

  // --- 文创商城 ---
  SET_PRODUCTS(state, data) {
    state.products = data
  },

  SET_PRODUCT_CATEGORIES(state, data) {
    state.productCategories = data
  },

  // --- 社区 ---
  SET_POSTS(state, data) {
    state.posts = data
  },

  // --- 地图 ---
  SET_MAP_POINTS(state, data) {
    state.mapPoints = data
  },

  // --- 搜索 ---
  SET_SEARCH_RESULTS(state, data) {
    state.searchResults = data
  },

  // --- 用户 ---
  SET_USER(state, { user, token }) {
    state.user = user
    state.token = token
    state.isLoggedIn = true
    // 持久化到 localStorage
    localStorage.setItem('user', JSON.stringify(user))
    localStorage.setItem('token', token)
  },

  LOGOUT(state) {
    state.user = null
    state.token = null
    state.isLoggedIn = false
    // 清除 localStorage
    localStorage.removeItem('user')
    localStorage.removeItem('token')
  },

  // --- 购物车 ---
  ADD_TO_CART(state, product) {
    const existing = state.cart.find(item => item.id === product.id)
    if (existing) {
      existing.quantity += product.quantity || 1
    } else {
      state.cart.push({ ...product, quantity: product.quantity || 1 })
    }
    localStorage.setItem('cart', JSON.stringify(state.cart))
  },

  REMOVE_FROM_CART(state, productId) {
    state.cart = state.cart.filter(item => item.id !== productId)
    localStorage.setItem('cart', JSON.stringify(state.cart))
  },

  UPDATE_CART_QUANTITY(state, { productId, quantity }) {
    const item = state.cart.find(item => item.id === productId)
    if (item) {
      item.quantity = quantity
      if (quantity <= 0) {
        state.cart = state.cart.filter(i => i.id !== productId)
      }
    }
    localStorage.setItem('cart', JSON.stringify(state.cart))
  },

  CLEAR_CART(state) {
    state.cart = []
    localStorage.removeItem('cart')
  }
}

