// ===== Getters =====
const getters = {
  // 是否已登录
  isAuthenticated: (state) => state.isLoggedIn && !!state.token,

  // 购物车商品总数
  cartCount: (state) => {
    return state.cart.reduce((total, item) => total + (item.quantity || 1), 0)
  },

  // 购物车总价
  cartTotal: (state) => {
    return state.cart.reduce((total, item) => {
      return total + (item.price || 0) * (item.quantity || 1)
    }, 0)
  },

  // 根据 ID 查找非遗项目
  heritageById: (state) => (id) => {
    return state.heritages.find(h => h.id === id)
  },

  // 根据 ID 查找传承人
  inheritorById: (state) => (id) => {
    return state.inheritors.find(i => i.id === id)
  },

  // 根据 ID 查找课程
  courseById: (state) => (id) => {
    return state.courses.find(c => c.id === id)
  },

  // 根据 ID 查找视频
  videoById: (state) => (id) => {
    return state.videos.find(v => v.id === id)
  },

  // 根据 ID 查找商品
  productById: (state) => (id) => {
    return state.products.find(p => p.id === id)
  }
}

// 创建 Store 实例
const store = createStore({
  state,
  mutations,
  actions,
  getters
})

export default store
