/**
 * Vue Router 配置
 * 
 * 路由模式: History Mode (createWebHistory)
 * 路由数量: 14 个页面路由
 * 特性:
 * - 路由懒加载 (代码分割)
 * - 页面切换滚动到顶部
 * - 统一的页面标题
 */

import { createRouter, createWebHistory } from 'vue-router'

// 路由配置
const routes = [
  {
    path: '/',
    name: 'Home',
    component: () => import('@/views/HomeView.vue'),
    meta: {
      title: '首页',
      description: '荆楚非遗概览，传承千年楚文化'
    }
  },
  {
    path: '/heritage',
    name: 'Heritage',
    component: () => import('@/views/HeritageView.vue'),
    meta: {
      title: '非遗概览',
      description: '探索湖北丰富的非物质文化遗产'
    }
  },
  {
    path: '/inheritors',
    name: 'Inheritors',
    component: () => import('@/views/InheritorsView.vue'),
    meta: {
      title: '传承人',
      description: '认识守护非遗技艺的传承人们'
    }
  },
  {
    path: '/learning',
    name: 'Learning',
    component: () => import('@/views/LearningView.vue'),
    meta: {
      title: '在线学习',
      description: '非遗技艺在线课程学习'
    }
  },
  {
    path: '/videos',
    name: 'Videos',
    component: () => import('@/views/VideosView.vue'),
    meta: {
      title: '视听中心',
      description: '非遗纪录片、教学视频、演出录像'
    }
  },
  {
    path: '/news',
    name: 'News',
    component: () => import('@/views/NewsView.vue'),
    meta: {
      title: '非遗资讯',
      description: '非遗保护动态、传承人故事、展览活动'
    }
  },
  {
    path: '/map',
    name: 'Map',
    component: () => import('@/views/MapView.vue'),
    meta: {
      title: '非遗地图',
      description: '探索湖北非遗文化地图'
    }
  },
  {
    path: '/shop',
    name: 'Shop',
    component: () => import('@/views/ShopView.vue'),
    meta: {
      title: '文创商城',
      description: '非遗文创产品、学习材料'
    }
  },
  {
    path: '/community',
    name: 'Community',
    component: () => import('@/views/CommunityView.vue'),
    meta: {
      title: '交流社区',
      description: '非遗爱好者交流社区'
    }
  },
  {
    path: '/search',
    name: 'Search',
    component: () => import('@/views/SearchView.vue'),
    meta: {
      title: '搜索',
      description: '全站搜索'
    }
  },
  {
    path: '/login',
    name: 'Login',
    component: () => import('@/views/LoginView.vue'),
    meta: {
      title: '登录',
      description: '登录您的账户',
      guestOnly: true
    }
  },
  {
    path: '/register',
    name: 'Register',
    component: () => import('@/views/RegisterView.vue'),
    meta: {
      title: '注册',
      description: '创建新账户',
      guestOnly: true
    }
  },
  {
    path: '/about',
    name: 'About',
    component: () => import('@/views/AboutView.vue'),
    meta: {
      title: '关于我们',
      description: '关于荆楚遗韵平台'
    }
  }
]

const router = createRouter({
  history: createWebHistory(),
  routes,
  // 页面切换时滚动到顶部
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }
    return { top: 0, behavior: 'smooth' }
  }
})

// 全局前置守卫 - 更新页面标题
router.beforeEach((to, from, next) => {
  // 更新页面标题
  const title = to.meta.title
    ? `${to.meta.title} - 荆楚遗韵`
    : '荆楚遗韵 - 湖北非物质文化遗产数字平台'
  document.title = title
  next()
})

export default router
