<script setup>
/**
 * App.vue - 应用根组件
 * 
 * 布局结构:
 * - AppHeader: 顶部导航栏 (固定定位)
 * - router-view: 页面内容区域
 * - AppFooter: 底部页脚
 * 
 * 全局功能:
 * - 页面切换过渡动画 (fade)
 * - Toast/通知容器
 * - 全局 loading 状态监听
 */

import { computed, watch } from 'vue'
import { useStore } from 'vuex'
import { useRoute } from 'vue-router'
import AppHeader from '@/components/AppHeader.vue'
import AppFooter from '@/components/AppFooter.vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'

const store = useStore()
const route = useRoute()

// 全局 loading 状态
const isLoading = computed(() => store.state.loading)

// 全局错误状态
const globalError = computed(() => store.state.error)

// 监听路由变化，清除错误状态
watch(
  () => route.path,
  () => {
    if (store.state.error) {
      store.commit('CLEAR_ERROR')
    }
  }
)

// 清除全局错误
const clearError = () => {
  store.commit('CLEAR_ERROR')
}
</script>

<template>
  <div id="app-root" class="app-root">
    <!-- 顶部导航栏 -->
    <AppHeader />

    <!-- 全局 Loading 遮罩 -->
    <Transition name="fade">
      <div v-if="isLoading" class="global-loading-overlay">
        <LoadingSpinner size="large" text="加载中..." />
      </div>
    </Transition>

    <!-- 全局错误提示 -->
    <Transition name="slide-down">
      <div v-if="globalError" class="global-error-banner">
        <span class="error-icon">⚠️</span>
        <span class="error-message">{{ globalError }}</span>
        <button class="error-close" @click="clearError" aria-label="关闭错误提示">
          ✕
        </button>
      </div>
    </Transition>

    <!-- 页面内容区域 -->
    <main class="main-content">
      <RouterView v-slot="{ Component }">
        <Transition name="fade" mode="out-in">
          <component :is="Component" />
        </Transition>
      </RouterView>
    </main>

    <!-- 底部页脚 -->
    <AppFooter />
  </div>
</template>

<style scoped>
