/**
 * 荆楚遗韵 - Vue 3 应用入口文件
 * 
 * 功能:
 * - 创建 Vue 3 应用实例
 * - 注册 Vue Router 和 Vuex Store
 * - 挂载应用到 #app 元素
 */

import { createApp } from 'vue'
import App from './App.vue'
import router from './router'
import store from './store'

const app = createApp(App)

// 注册 Vuex Store (必须在路由之前，确保全局状态可用)
app.use(store)

// 注册 Vue Router
app.use(router)

// 挂载应用
app.mount('#app')
